import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.CdvW4CUT.js";const m=JSON.parse('{"title":"展示框保護套件","description":"說明展示框保護套件的使用方式。","frontmatter":{"title":"展示框保護套件","description":"說明展示框保護套件的使用方式。"},"headers":[],"relativePath":"feature/sp_tool_itemframe/index.md","filePath":"feature/sp_tool_itemframe.md"}'),r={name:"feature/sp_tool_itemframe/index.md"};function o(h,a,s,n,u,d){return t(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="功能性道具-展示框保護套件-隱形展示框" tabindex="-1">功能性道具 - 展示框保護套件 / 隱形展示框 <a class="header-anchor" href="#功能性道具-展示框保護套件-隱形展示框" aria-label="Permalink to &quot;功能性道具 - 展示框保護套件 / 隱形展示框&quot;">​</a></h1><h2 id="說明" tabindex="-1">說明 <a class="header-anchor" href="#說明" aria-label="Permalink to &quot;說明&quot;">​</a></h2><p>可以用來保護你的展示框，使他如同鎖住的箱子一樣，不會被其他人摧毀</p><ul><li>其他人無法旋轉與打下你在展示框上的物品，也無法打掉展示框</li><li>任何怪物/爆炸/弓箭...皆無法對展示框造成影響</li><li>若被方塊擠壓，或是懸浮在空中，也不會掉下來</li></ul><img src="https://i.imgur.com/U2MxSuS.png" style="width:70%;"><h3 id="取得方式" tabindex="-1">取得方式 <a class="header-anchor" href="#取得方式" aria-label="Permalink to &quot;取得方式&quot;">​</a></h3><ul><li>大廳服重生點旁的商人</li><li>售價：每64個 1獄髓碇 + 8鑽石磚</li><li>一次性道具，使用後消失</li></ul><h3 id="使用方式" tabindex="-1">使用方式 <a class="header-anchor" href="#使用方式" aria-label="Permalink to &quot;使用方式&quot;">​</a></h3><ul><li>首先，請先將展示框與要展示的物品放在展示框上<br> 並且手持 <code>展示框保護套件</code> 對該展示框點擊&quot;左鍵&quot;<br><img src="https://i.imgur.com/gHVhL4w.png" style="height:30%;width:30%;"></li><li>這樣就保護完成了</li></ul><h3 id="注意事項" tabindex="-1">注意事項 <a class="header-anchor" href="#注意事項" aria-label="Permalink to &quot;注意事項&quot;">​</a></h3><ul><li>保護後的展示框，如果你打掉(取下)該物品，展示框會直接連同物品掉落。</li></ul><h2 id="隱形展示框" tabindex="-1">隱形展示框 <a class="header-anchor" href="#隱形展示框" aria-label="Permalink to &quot;隱形展示框&quot;">​</a></h2><ul><li>隱形條件：展示框必須先保護，才能進行隱形</li><li>使用方式：手持金色胡蘿蔔，對你保護的展示框點擊&quot;左鍵&quot;，即可將之隱形<br><img src="https://i.imgur.com/OW8lhkh.png" style="height:30%;width:30%;"></li></ul><p><font size="4"><a href="/feature/sp_tool/"><b>點我返回 特殊道具</b></a></font></p>',14)])])}const _=e(r,[["render",o]]);export{m as __pageData,_ as default};
